//! Real Git/CAS projection and verifier regressions. Permission normalization
//! must not weaken content checks or invent a prior receipt on cold paths.
use super::*;
use jj_lib::{config::{ConfigLayer,ConfigSource,StackedConfig},repo::Repo,settings::UserSettings,workspace::Workspace};
use std::{fs,os::unix::fs::{MetadataExt,PermissionsExt},path::PathBuf,time::Duration};
struct Fixture{_temp:tempfile::TempDir,_workspace:Workspace,repo:Arc<jj_lib::repo::ReadonlyRepo>,cas:LocalStore,stage:String,policy:ObjectRef}
impl Fixture{
 fn new()->Self{let temporary=if Path::new("/workspace").is_dir(){tempfile::tempdir_in("/workspace").unwrap()}else{tempfile::tempdir().unwrap()};let root=temporary.path().canonicalize().unwrap();let private=root.join("integration");fs::create_dir(&private).unwrap();let mut config=StackedConfig::with_defaults();let mut layer=ConfigLayer::empty(ConfigSource::User);layer.set_value("user.name","mode reuse fixture").unwrap();layer.set_value("user.email","mode@invalid.example").unwrap();config.add_layer(layer);let settings=UserSettings::from_config(config).unwrap();let(workspace,repo)=pollster::block_on(Workspace::init_internal_git(&settings,&private)).unwrap();let cas=LocalStore::open(root.join("cas")).unwrap();let stage=cas.begin_staging(Duration::from_secs(120)).unwrap().id;let policy=cas.put_blob(&canonical_json(&crate::vfs_provider::SourceProjectionPolicy::from_import_policy(&rudder_engine::workspace::WorkspaceProfile::source_only().source_exclusions()).unwrap()).unwrap()).unwrap();Self{_temp:temporary,_workspace:workspace,repo,cas,stage,policy}}
 fn baseline(&self)->MergedTree{self.repo.store().get_commit(self.repo.view().get_wc_commit_id(jj_lib::ref_name::WorkspaceName::DEFAULT).unwrap()).unwrap().tree()}
 fn directory(&self,files:&[(&str,&[u8],u32)])->ObjectRef{let adapter=LocalDirectoryStore::new(&self.cas,&self.stage);let mut entries=files.iter().map(|(name,bytes,mode)|DirectoryEntry::new(name.as_bytes(),EntryNode::File{object:self.cas.put_blob(bytes).unwrap(),logical_size:bytes.len()as u64,mode:*mode}).unwrap()).collect::<Vec<_>>();entries.sort_by(|a,b|a.name_hex.cmp(&b.name_hex));PagedDirectory::new(&adapter).build(0o755,entries).unwrap()}
 fn project(&self,root:&ObjectRef,baseline:&MergedTree,previous:Option<&ProjectionRecord>)->ProjectedSource{pollster::block_on(project_source(self.cas.clone(),root,baseline,&self.policy,None,previous,ProjectionBudget::default())).unwrap()}
 fn materialize(&self,tree:&MergedTree)->ProjectionRecord{pollster::block_on(materialize_source(self.cas.clone(),&self.stage,tree,&self.policy,None,ProjectionBudget::default())).unwrap().0}
 fn source(&self,directory:&ObjectRef)->ObjectRef{self.cas.put_metadata(ObjectKind::SourceRoot,&rudder_engine::snapshot::SourceV2{format_version:2,consistency:rudder_engine::protocol::CheckpointConsistency::Quiesced,directory:directory.clone(),projection_policy:self.policy.clone()}).unwrap()}
}
#[derive(Debug,Clone,PartialEq,Eq)]
struct Witness{id:Vec<u8>,executable:bool,path:PathBuf,dev:u64,ino:u64,len:u64,mode:u32,uid:u32,gid:u32,links:u64,mtime:(i64,i64),ctime:(i64,i64)}
fn witnesses(tree:&MergedTree)->BTreeMap<String,Witness>{let git=tree.store().backend_impl::<jj_lib::git_backend::GitBackend>().unwrap().git_repo_path();let mut out=BTreeMap::new();for(path,value)in tree.entries(){let value=value.unwrap();if let Some(Some(TreeValue::File{id,executable,..}))=value.as_resolved(){let hex=id.hex();let physical=git.join("objects").join(&hex[..2]).join(&hex[2..]);let m=fs::symlink_metadata(&physical).unwrap();assert!(m.is_file()&&!m.file_type().is_symlink());out.insert(path.as_internal_file_string().to_owned(),Witness{id:id.as_bytes().to_vec(),executable:*executable,path:physical,dev:m.dev(),ino:m.ino(),len:m.len(),mode:m.mode(),uid:m.uid(),gid:m.gid(),links:m.nlink(),mtime:(m.mtime(),m.mtime_nsec()),ctime:(m.ctime(),m.ctime_nsec())});}}out}
fn mode(record:&ProjectionRecord,name:&str)->u32{match &record.paths[name].source{EntryNode::File{mode,..}=>*mode,_=>panic!("file expected")}}
#[test]
fn materialized_prior_reuses_only_versioned_permission_semantics_and_keeps_raw_source_modes(){
 let f=Fixture::new();let files:[(&str,&[u8],u32);3]=[("private",b"private source bytes\n",0o600),("readonly",b"readonly source bytes\n",0o400),("tool",b"#!/bin/sh\necho tool\n",0o700)];let root=f.directory(&files);let first=f.project(&root,&f.baseline(),None);assert_eq!(first.work.reused_leaf_values,0);let before=witnesses(&first.tree);let prior=f.materialize(&first.tree);assert_eq!(mode(&prior,"private"),0o644);assert_eq!(mode(&prior,"readonly"),0o644);assert_eq!(mode(&prior,"tool"),0o755);assert_ne!(prior.directory,root,"the CAS snapshot retains the raw permission modes");
 let again=f.project(&root,&first.tree,Some(&prior));assert_eq!(again.work.reused_leaf_values,3);assert_eq!(again.work.cas_content_bytes,0);assert_eq!(again.work.git_blob_bytes_submitted,0);assert_eq!(JjTreeIdentity::from_jj(&again.tree),JjTreeIdentity::from_jj(&first.tree));assert_eq!(witnesses(&again.tree),before,"actual FileIDs and complete physical versions must stay unchanged");for(name,_,wanted)in files{assert_eq!(mode(&again.record,name),wanted,"the new receipt must preserve the exact candidate node");}
 let bytes=files.iter().map(|(_,b,_)|b.len()as u64).sum::<u64>();let cold=f.project(&root,&first.tree,None);assert_eq!(cold.work.reused_leaf_values,0);assert!(cold.work.cas_content_bytes>=bytes);assert_eq!(witnesses(&cold.tree),before);
 let source=f.source(&root);let verified=pollster::block_on(verify_versioned_source(f.cas.clone(),&f.stage,&source,&f.policy,&again.tree,Some(&again.record),ProjectionBudget::default())).unwrap();assert_eq!(verified.receipt().work.reused_leaf_values,0);assert!(verified.receipt().work.cas_content_bytes>=bytes);assert_eq!(witnesses(&again.tree),before);
 // Fast reuse remains an optimization only. The mandatory full verifier must
 // reject a corrupted CAS preimage even with the exact new mode-aware receipt.
 let EntryNode::File{object,..}=&again.record.paths["private"].source else{panic!()};let path=f.cas.object_path(object).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o644)).unwrap();fs::write(&path,vec![b'!';object.size_bytes as usize]).unwrap();fs::set_permissions(&path,fs::Permissions::from_mode(0o444)).unwrap();let pins=f.cas.retention().unwrap().pins;
 assert!(pollster::block_on(verify_versioned_source(f.cas.clone(),&f.stage,&source,&f.policy,&again.tree,Some(&again.record),ProjectionBudget::default())).is_err());assert_eq!(witnesses(&again.tree),before);assert_eq!(f.cas.retention().unwrap().pins,pins);
}
#[test]
fn actual_executable_bit_and_content_changes_still_miss_prior_reuse(){
 let f=Fixture::new();let root=f.directory(&[("file",b"original payload",0o600)]);let first=f.project(&root,&f.baseline(),None);let prior=f.materialize(&first.tree);let before=witnesses(&first.tree);
 let executable=f.directory(&[("file",b"original payload",0o700)]);let changed=f.project(&executable,&first.tree,Some(&prior));assert_eq!(changed.work.reused_leaf_values,0);assert!(changed.work.cas_content_bytes>=b"original payload".len()as u64);assert_ne!(JjTreeIdentity::from_jj(&changed.tree),JjTreeIdentity::from_jj(&first.tree));let actual=witnesses(&changed.tree);assert!(actual["file"].executable);assert_eq!(actual["file"].id,before["file"].id);let mut want=before["file"].clone();want.executable=true;assert_eq!(actual["file"],want,"mode edits must not rewrite identical blob bytes/inodes");
 let edited=f.directory(&[("file",b"modified payload",0o600)]);let edited=f.project(&edited,&first.tree,Some(&prior));assert_eq!(edited.work.reused_leaf_values,0);assert!(edited.work.cas_content_bytes>=b"modified payload".len()as u64);assert_ne!(witnesses(&edited.tree)["file"].id,before["file"].id);assert_eq!(witnesses(&first.tree),before,"changed content must not replace any old immutable blob");
}
